#!/usr/bin/env python3
"""Authentic TLG0086 payload for the 2026-08-17 Magna Moralia re-ingestion.

The 434 records were produced by a whole-work sequential alignment of the live
``passage_arist_mm_*`` descriptions against the Magna Moralia work in the local
TLG E disk file.  The 38 starts recorded by the earlier linguistic-repairs wave
are exact checkpoints (38/38 reproduced); four old inclusive ends that crossed
formatting or the next passage were tightened by the new global partition.
Replacement strings are mechanical beta-code decodings of the recorded
half-open byte spans: no Greek is generated or emended here.

The compact payload is compressed only to keep this additive data module at a
reviewable size.  ``MM_REINGEST_RECORDS`` exposes ordinary per-node dictionaries
with the node id, corpus UUID, TLG span, decoded Greek, old incipits, length
ratio, similarity, boundary method, and strictly ordered neighbour evidence.
"""

