def _load_records() -> tuple[dict, ...]:
    compressed = base64.b85decode("".join(_PAYLOAD_B85.split()))
    blob = zlib.decompress(compressed)
    if hashlib.sha256(blob).hexdigest() != _PAYLOAD_SHA256:
        raise RuntimeError("Magna Moralia re-ingestion payload checksum mismatch")
    rows = json.loads(blob.decode("utf-8"))
    records = []
    for index, row in enumerate(rows):
        (
            node_id,
            corpus_uuid,
            canonical_ref,
            start_byte,
            end_byte,
            expected_old_incipit,
            expected_old_corpus_incipit,
            old_length,
            replacement_length,
            span_length_ratio,
            base_letter_similarity,
            boundary_alignment,
            replacement_greek,
        ) = row
        previous = rows[index - 1] if index else None
        following = rows[index + 1] if index + 1 < len(rows) else None
        records.append(
            {
                "node_id": node_id,
                "corpus_uuid": corpus_uuid,
                "canonical_ref": canonical_ref,
                "tlg_anchor": {
                    "start_byte": start_byte,
                    "end_byte": end_byte,
                },
                "replacement_greek": replacement_greek,
                "expected_old_incipit": expected_old_incipit,
                "expected_old_corpus_incipit": expected_old_corpus_incipit,
                "anchor_evidence": {
                    "method": "whole-work word alignment + local difflib verification",
                    "prior_linguistic_anchor_checkpoint": (
                        node_id in PRIOR_LINGUISTIC_ANCHOR_IDS
                    ),
                    "boundary_alignment": boundary_alignment,
                    "base_letter_similarity": base_letter_similarity,
                    "old_char_length": old_length,
                    "replacement_char_length": replacement_length,
                    "span_length_ratio": span_length_ratio,
                    "ratio_justification": None,
                    "previous_node_id": previous[0] if previous else None,
                    "previous_end_byte": previous[4] if previous else None,
                    "next_node_id": following[0] if following else None,
                    "next_start_byte": following[3] if following else None,
                },
            }
        )
    return tuple(records)


MM_REINGEST_RECORDS = _load_records()

assert len(MM_REINGEST_RECORDS) == RECORD_COUNT
assert len(PRIOR_LINGUISTIC_ANCHOR_IDS) == 38
assert len({row["node_id"] for row in MM_REINGEST_RECORDS}) == RECORD_COUNT
assert len({row["corpus_uuid"] for row in MM_REINGEST_RECORDS}) == RECORD_COUNT
assert all(
    left["tlg_anchor"]["end_byte"] < right["tlg_anchor"]["start_byte"]
    for left, right in zip(
        MM_REINGEST_RECORDS, MM_REINGEST_RECORDS[1:], strict=False
    )
)
assert all(
    0.8 <= row["anchor_evidence"]["span_length_ratio"] <= 1.25
    for row in MM_REINGEST_RECORDS
)
